import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.CvydjLy7.js";const c=JSON.parse('{"title":"9.11 没有 Docker 的环境，怎么收场","description":"","frontmatter":{"title":"9.11 没有 Docker 的环境，怎么收场"},"headers":[{"level":3,"title":"第一种：显式声明“没有 Docker 就跳过”","slug":"第一种-显式声明-没有-docker-就跳过","link":"#第一种-显式声明-没有-docker-就跳过","children":[]},{"level":3,"title":"第二种：连得上 Docker，但拉不到镜像","slug":"第二种-连得上-docker-但拉不到镜像","link":"#第二种-连得上-docker-但拉不到镜像","children":[]},{"level":3,"title":"第三种：把容器当成可选组件","slug":"第三种-把容器当成可选组件","link":"#第三种-把容器当成可选组件","children":[]}],"relativePath":"ch09/11.md","filePath":"ch09/11.md","lastUpdated":1789497795000}'),n={name:"ch09/11.md"};function l(p,s,r,h,o,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="_9-11-没有-docker-的环境-怎么收场" tabindex="-1">9.11 没有 Docker 的环境，怎么收场 <a class="header-anchor" href="#_9-11-没有-docker-的环境-怎么收场" aria-label="Permalink to &quot;9.11 没有 Docker 的环境，怎么收场&quot;">​</a></h1><p>Testcontainers 的前提是本机能跑容器。CI 跑在受限容器里、同事机器上没装 Docker、或者像本篇这台机器一样连不上 Docker Hub——这些都会让测试直接失败。要把“环境不具备”和“代码有 bug”区分开。</p><h3 id="第一种-显式声明-没有-docker-就跳过" tabindex="-1">第一种：显式声明“没有 Docker 就跳过” <a class="header-anchor" href="#第一种-显式声明-没有-docker-就跳过" aria-label="Permalink to &quot;第一种：显式声明“没有 Docker 就跳过”&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Testcontainers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">disabledWithoutDocker</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MySqlContainerIntegrationTest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { ... }</span></span></code></pre></div><p><code>disabledWithoutDocker</code> 是 <code>@Testcontainers</code> 自带的属性。加上它之后，没有 Docker 时整类测试会被<strong>跳过</strong>（报告里显示 skipped），而不是失败。这样 CI 上“缺环境”不会被误读成“代码有问题”。</p><h3 id="第二种-连得上-docker-但拉不到镜像" tabindex="-1">第二种：连得上 Docker，但拉不到镜像 <a class="header-anchor" href="#第二种-连得上-docker-但拉不到镜像" aria-label="Permalink to &quot;第二种：连得上 Docker，但拉不到镜像&quot;">​</a></h3><p>这是本篇实测遇到的真实情况：Docker daemon 正常，但 <code>registry-1.docker.io</code> 直连超时。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error response from daemon: Get &quot;https://registry-1.docker.io/v2/&quot;:</span></span>
<span class="line"><span>context deadline exceeded</span></span></code></pre></div><p>Testcontainers 除了被测容器，还要拉一个自己的<strong>活动回收容器</strong>（<code>testcontainers/ryuk</code>），它的作用是 JVM 意外退出时兜底清理容器。拉不到它，测试会卡在重试里：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WARN  tc.testcontainers/ryuk:0.14.0 : Retrying pull for image: testcontainers/ryuk:0.14.0 (104s remaining)</span></span></code></pre></div><p>处理顺序建议是这样：</p><p><strong>首选配镜像加速器。</strong> 如果 Docker 已经配了 <code>registry-mirrors</code> 但拉取仍然走直连，说明配置没有被读取（改完要重启 Docker），或者加速器里没有缓存这个镜像。可以先手工验证加速器是否可达：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 返回 401 是正常的：registry v2 需要认证，能返回状态码就说明网络通</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%{http_code}\\n&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-time</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://docker.1ms.run/v2/</span></span></code></pre></div><p><strong>实在拉不到，临时关掉 ryuk：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TESTCONTAINERS_RYUK_DISABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>代价要说清楚：关掉 ryuk 只是<strong>失去了 JVM 崩溃时的兜底清理</strong>。正常路径下，<code>@Container</code> 的生命周期管理在测试结束时仍然会调用 <code>stop()</code> 把容器停掉。所以它适合本地临时跑通，不适合当成长期配置。</p><p>本篇全量测试就是这么跑下来的：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TESTCONTAINERS_RYUK_DISABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><h3 id="第三种-把容器当成可选组件" tabindex="-1">第三种：把容器当成可选组件 <a class="header-anchor" href="#第三种-把容器当成可选组件" aria-label="Permalink to &quot;第三种：把容器当成可选组件&quot;">​</a></h3><p>如果团队里大部分人不跑 Docker，可以把 Testcontainers 相关的用例独立成一套、用 Maven profile 或 JUnit tag 隔离，让默认构建不依赖 Docker。做法本身没有对错，关键是要<strong>显式声明</strong>，不要让它变成“在我机器上是绿的”。</p><hr>`,21)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
